function setLang(lang){
  var dict = I18N[lang] || I18N.cs;
  document.documentElement.lang = lang;
  document.querySelectorAll('[data-i18n]').forEach(function(el){
    var key = el.getAttribute('data-i18n');
    if (dict[key]) el.textContent = dict[key];
  });
  document.querySelectorAll('.lang-switch button').forEach(function(b){
    b.classList.toggle('active', b.dataset.lang === lang);
  });
}

document.addEventListener('DOMContentLoaded', function () {

  /* intro animation: logo appears center-stage, then glides to its header position */
  (function runIntro() {
    var overlay = document.getElementById('intro-overlay');
    var logo = document.getElementById('intro-logo');
    var target = document.querySelector('.brand-logo img');
    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (!overlay || !logo || !target || reduceMotion || typeof logo.animate !== 'function') {
      if (overlay) overlay.remove();
      return;
    }

    document.body.classList.add('intro-lock');

    logo.animate(
      [{ opacity: 0, transform: 'scale(.92)' }, { opacity: 1, transform: 'scale(1)' }],
      { duration: 420, easing: 'cubic-bezier(.16,.84,.44,1)', fill: 'forwards' }
    );

    setTimeout(function () {
      var startRect = logo.getBoundingClientRect();
      var endRect = target.getBoundingClientRect();
      var scale = endRect.width / startRect.width;
      var dx = (endRect.left + endRect.width / 2) - (startRect.left + startRect.width / 2);
      var dy = (endRect.top + endRect.height / 2) - (startRect.top + startRect.height / 2);

      var move = logo.animate(
        [
          { transform: 'translate(0,0) scale(1)', opacity: 1 },
          { transform: 'translate(' + dx + 'px,' + dy + 'px) scale(' + scale + ')', opacity: .95 }
        ],
        { duration: 620, easing: 'cubic-bezier(.16,.84,.44,1)', fill: 'forwards' }
      );

      move.onfinish = function () {
        overlay.style.transition = 'opacity .3s ease';
        overlay.style.opacity = '0';
        document.body.classList.remove('intro-lock');
        setTimeout(function () { overlay.remove(); }, 320);
      };
    }, 430);
  })();

  /* language switch */
  document.querySelectorAll('.lang-switch button').forEach(function(btn){
    btn.addEventListener('click', function(){ setLang(btn.dataset.lang); });
  });

  /* header scroll state */
  var header = document.querySelector('.site-header');
  var onScroll = function () {
    if (header) header.classList.toggle('scrolled', window.scrollY > 24);
  };
  document.addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  /* scroll-spy side nav */
  var dots = document.querySelectorAll('.side-nav a');
  var sections = Array.from(dots).map(function (a) {
    return document.querySelector(a.getAttribute('href'));
  }).filter(Boolean);
  if (sections.length && 'IntersectionObserver' in window) {
    var spy = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        var id = '#' + entry.target.id;
        dots.forEach(function (a) { a.classList.toggle('active', a.getAttribute('href') === id); });
      });
    }, { rootMargin: '-45% 0px -45% 0px', threshold: 0 });
    sections.forEach(function (s) { spy.observe(s); });
  }

  /* scroll reveal */
  var revealEls = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window && revealEls.length) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) { entry.target.classList.add('in'); io.unobserve(entry.target); }
      });
    }, { threshold: 0.12 });
    revealEls.forEach(function (el) { io.observe(el); });
  } else {
    revealEls.forEach(function (el) { el.classList.add('in'); });
  }

  /* draggable timeline */
  var track = document.querySelector('.timeline-track');
  if (track) {
    var isDown = false, startX, scrollLeft;
    track.addEventListener('mousedown', function (e) {
      isDown = true; track.classList.add('dragging');
      startX = e.pageX - track.offsetLeft; scrollLeft = track.scrollLeft;
    });
    ['mouseleave', 'mouseup'].forEach(function (evt) {
      track.addEventListener(evt, function () { isDown = false; track.classList.remove('dragging'); });
    });
    track.addEventListener('mousemove', function (e) {
      if (!isDown) return;
      e.preventDefault();
      var x = e.pageX - track.offsetLeft;
      track.scrollLeft = scrollLeft - (x - startX) * 1.2;
    });
    track.setAttribute('tabindex', '0');
    track.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowRight') track.scrollBy({ left: 260, behavior: 'smooth' });
      if (e.key === 'ArrowLeft') track.scrollBy({ left: -260, behavior: 'smooth' });
    });
  }

  /* animated counters */
  /* hero watermark parallax — moves slower than the page */
  var heroWM = document.querySelector('.hero-watermark');
  if (heroWM && window.matchMedia('(min-width:901px)').matches) {
    var wmRaf = null;
    var updateWM = function () {
      var y = window.scrollY * 0.12;
      heroWM.style.transform = 'translate(-50%, calc(-50% + ' + y + 'px))';
      wmRaf = null;
    };
    document.addEventListener('scroll', function () {
      if (!wmRaf) wmRaf = requestAnimationFrame(updateWM);
    }, { passive: true });
  }

  /* gallery filter */
  var galleryTabs = document.querySelectorAll('.ref-tabs button');
  var galleryItems = document.querySelectorAll('.gallery-item');
  if (galleryTabs.length && galleryItems.length) {
    galleryTabs.forEach(function (btn) {
      btn.addEventListener('click', function () {
        galleryTabs.forEach(function (b) { b.classList.remove('active'); });
        btn.classList.add('active');
        var filter = btn.getAttribute('data-filter');
        galleryItems.forEach(function (item) {
          var show = filter === 'all' || item.getAttribute('data-cat') === filter;
          item.classList.toggle('is-hidden', !show);
        });
      });
    });
  }

  var counters = document.querySelectorAll('[data-count]');
  if (counters.length && 'IntersectionObserver' in window) {
    var counted = new WeakSet();
    var cio = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting || counted.has(entry.target)) return;
        counted.add(entry.target);
        var el = entry.target;
        var target = parseInt(el.getAttribute('data-count'), 10);
        var start = null;
        var dur = 1200;
        function step(ts) {
          if (!start) start = ts;
          var progress = Math.min((ts - start) / dur, 1);
          var eased = 1 - Math.pow(1 - progress, 3);
          el.textContent = Math.round(eased * target);
          if (progress < 1) requestAnimationFrame(step);
          else el.textContent = target;
        }
        requestAnimationFrame(step);
      });
    }, { threshold: 0.4 });
    counters.forEach(function (el) { cio.observe(el); });
  }

  /* apply Czech by default so the initial render is fully localized */
  setLang('cs');
});


