/* ---------- selected productions: category icons ---------- */
const PF_ICONS = {
  film: '<svg viewBox="0 0 24 24" fill="none" stroke-width="1.1"><path d="M4 7h16l-2 13H6L4 7Z"/><path d="M9 7V5a3 3 0 0 1 6 0v2"/></svg>',
  tv:   '<svg viewBox="0 0 24 24" fill="none" stroke-width="1.1"><rect x="3" y="5" width="18" height="13" rx="1"/><path d="M8 21h8M12 18v3"/></svg>',
  ad:   '<svg viewBox="0 0 24 24" fill="none" stroke-width="1.1"><path d="M3 10v4h4l6 4V6l-6 4H3Z"/><path d="M16 9a4 4 0 0 1 0 6"/></svg>'
};
const PF_CAT_LABEL = { film: "Celovečerní film", tv: "Televizní seriál", ad: "Reklama" };

let pfCurrentIndex = 0;
let pfFilteredIndexes = PROJECTS.map((_, i) => i);

function pfRenderGrid() {
  const grid = document.getElementById('portfolio-grid');
  if (!grid) return;
  grid.innerHTML = PROJECTS.map((p, i) => `
    <div class="portfolio-card reveal in" data-idx="${i}" data-cat="${p.category}">
      <div class="pc-media">
        <img src="${p.cover}" alt="${p.title}" loading="lazy" onerror="this.style.display='none'">
        <div class="pc-icon">${PF_ICONS[p.category]}</div>
      </div>
      <div class="pc-overlay">
        <span class="pc-cat">${PF_CAT_LABEL[p.category]}</span>
        <h3 class="pc-title">${p.title}</h3>
        ${p.year ? `<span class="pc-year">${p.year}</span>` : ''}
      </div>
      <div class="pc-plus">
        <svg class="pc-plus-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 5v14M5 12h14"/></svg>
        <svg class="pc-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
      </div>
    </div>
  `).join('');

  grid.querySelectorAll('.portfolio-card').forEach(card => {
    card.addEventListener('click', () => pfOpen(parseInt(card.getAttribute('data-idx'), 10)));
  });
}

function pfApplyFilter(filter) {
  const cards = document.querySelectorAll('.portfolio-card');
  cards.forEach(card => {
    const show = filter === 'all' || card.getAttribute('data-cat') === filter;
    card.classList.toggle('is-hidden', !show);
  });
  pfFilteredIndexes = PROJECTS.map((p, i) => i).filter(i => filter === 'all' || PROJECTS[i].category === filter);
}

const PF_INDUSTRY_DEFAULT = { film: "Filmová produkce", tv: "Televizní produkce", ad: "Reklama" };
const PF_STRIP_LABELS = ["Úvod", "Detail", "Výroba", "Výsledek"];

function pfSetHero(src) {
  const hero = document.getElementById('pfd-hero-img');
  hero.style.backgroundImage = src ? `url("${src}")` : '';
}

function pfRenderStrip(photos) {
  const wrap = document.getElementById('pfd-strip');
  wrap.innerHTML = photos.map((src, i) => `
    <div class="pfd-shot ${src ? '' : 'is-hidden'}" data-i="${i}">
      <img src="${src || ''}" alt="" onerror="this.parentElement.classList.add('is-hidden')">
      <span class="pfd-shot-label">${PF_STRIP_LABELS[i] || ''}</span>
    </div>
  `).join('');
  wrap.querySelectorAll('.pfd-shot').forEach(shot => {
    shot.addEventListener('click', () => {
      const i = parseInt(shot.getAttribute('data-i'), 10);
      pfdViewerOpen(photos, i);
    });
  });
}

let pfdViewerPhotos = [];
let pfdViewerIndex = 0;

function pfdViewerShow(i) {
  pfdViewerIndex = (i + pfdViewerPhotos.length) % pfdViewerPhotos.length;
  document.getElementById('pfd-viewer-img').src = pfdViewerPhotos[pfdViewerIndex];
}

function pfdViewerOpen(photos, startIndex) {
  pfdViewerPhotos = photos.filter(Boolean);
  const viewer = document.getElementById('pfd-viewer');
  pfdViewerShow(startIndex);
  viewer.classList.add('open');
  viewer.setAttribute('aria-hidden', 'false');
}

function pfdViewerClose() {
  const viewer = document.getElementById('pfd-viewer');
  viewer.classList.remove('open');
  viewer.setAttribute('aria-hidden', 'true');
}

function pfShow(index) {
  const p = PROJECTS[index];
  if (!p) return;
  pfCurrentIndex = index;

  const storyPhotos = (p.images && p.images.length ? p.images : []).slice(0, 4);
  while (storyPhotos.length < 4) storyPhotos.push(null);

  pfSetHero(p.hero || p.cover);
  pfRenderStrip(storyPhotos);

  document.getElementById('pfd-title').textContent = p.title.toUpperCase();
  document.getElementById('pfd-hero-meta').textContent =
    PF_CAT_LABEL[p.category] + (p.year ? ' • ' + p.year : '');

  document.getElementById('pfd-story').textContent = p.description || '';

  const rows = {
    year: p.year,
    category: PF_CAT_LABEL[p.category],
    industry: p.industry || PF_INDUSTRY_DEFAULT[p.category] || '',
    scope: p.scope || (p.delivery && p.delivery.length ? p.delivery.join(', ') : ''),
    location: p.location
  };
  Object.keys(rows).forEach(key => {
    const row = document.getElementById('pfd-row-' + key);
    const val = document.getElementById('pfd-' + key);
    val.textContent = rows[key] || '';
    row.classList.toggle('is-empty', !rows[key]);
  });

  document.getElementById('pfd-scroll').scrollTo({ top: 0, behavior: 'instant' });
}

function pfOpen(index) {
  pfShow(index);
  const lb = document.getElementById('pf-lightbox');
  lb.classList.add('open');
  lb.setAttribute('aria-hidden', 'false');
  document.body.classList.add('intro-lock');
}

function pfClose() {
  const lb = document.getElementById('pf-lightbox');
  lb.classList.remove('open');
  lb.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('intro-lock');
}

function pfStep(dir) {
  if (!pfFilteredIndexes.length) return;
  let pos = pfFilteredIndexes.indexOf(pfCurrentIndex);
  if (pos === -1) pos = 0;
  pos = (pos + dir + pfFilteredIndexes.length) % pfFilteredIndexes.length;
  pfShow(pfFilteredIndexes[pos]);
}

document.addEventListener('DOMContentLoaded', function () {
  pfRenderGrid();
  pfApplyFilter('all');

  document.querySelectorAll('[data-pf-filter]').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('[data-pf-filter]').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      pfApplyFilter(btn.getAttribute('data-pf-filter'));
    });
  });

  const closeBtn = document.getElementById('pf-close');
  const prevBtn = document.getElementById('pf-prev');
  const nextBtn = document.getElementById('pf-next');
  const lb = document.getElementById('pf-lightbox');
  if (closeBtn) closeBtn.addEventListener('click', pfClose);
  if (prevBtn) prevBtn.addEventListener('click', () => pfStep(-1));
  if (nextBtn) nextBtn.addEventListener('click', () => pfStep(1));
  if (lb) lb.addEventListener('click', (e) => { if (e.target === lb) pfClose(); });

  const contactBtn = document.getElementById('pfd-contact');
  if (contactBtn) contactBtn.addEventListener('click', () => { pfClose(); });

  const viewer = document.getElementById('pfd-viewer');
  const viewerClose = document.getElementById('pfd-viewer-close');
  const viewerPrev = document.getElementById('pfd-viewer-prev');
  const viewerNext = document.getElementById('pfd-viewer-next');
  if (viewerClose) viewerClose.addEventListener('click', pfdViewerClose);
  if (viewerPrev) viewerPrev.addEventListener('click', () => pfdViewerShow(pfdViewerIndex - 1));
  if (viewerNext) viewerNext.addEventListener('click', () => pfdViewerShow(pfdViewerIndex + 1));
  if (viewer) viewer.addEventListener('click', (e) => { if (e.target === viewer) pfdViewerClose(); });

  document.addEventListener('keydown', (e) => {
    if (viewer && viewer.classList.contains('open')) {
      if (e.key === 'Escape') pfdViewerClose();
      if (e.key === 'ArrowLeft') pfdViewerShow(pfdViewerIndex - 1);
      if (e.key === 'ArrowRight') pfdViewerShow(pfdViewerIndex + 1);
      return;
    }
    if (!lb || !lb.classList.contains('open')) return;
    if (e.key === 'Escape') pfClose();
    if (e.key === 'ArrowLeft') pfStep(-1);
    if (e.key === 'ArrowRight') pfStep(1);
  });
});
